export function normalize(intervals) {
  // Validate input
  validateIntervalList(intervals);

  // Handle empty input
  if (intervals.length === 0) {
    return [];
  }

  // Filter out empty intervals and create copies
  const filtered = intervals
    .filter(interval => interval[0] < interval[1])
    .map(interval => [interval[0], interval[1]]);

  // If all intervals were empty, return empty array
  if (filtered.length === 0) {
    return [];
  }

  // Sort by start value
  filtered.sort((a, b) => a[0] - b[0]);

  // Coalesce overlapping or touching intervals
  const result = [filtered[0]];

  for (let i = 1; i < filtered.length; i++) {
    const current = filtered[i];
    const last = result[result.length - 1];

    // If current interval overlaps or touches the last one in result, merge them
    if (current[0] <= last[1]) {
      last[1] = Math.max(last[1], current[1]);
    } else {
      // No overlap/touch, add as new interval
      result.push([current[0], current[1]]);
    }
  }

  return result;
